topic_count:
query($topicName: String!) {
  topic(name: $topicName) {
    name
    stargazerCount
    repositories {
      totalCount
    }
  }
  rateLimit {
    limit
    remaining
    resetAt
  }
}

search_page:
query($searchQuery: String!, $cursor: String) {
  search(query: $searchQuery, type: REPOSITORY, first: 100, after: $cursor) {
    repositoryCount
    pageInfo {
      hasNextPage
      endCursor
    }
    nodes {
      ... on Repository {
        id
        databaseId
        name
        nameWithOwner
        description
        stargazerCount
        forkCount
        url
        primaryLanguage {
          name
        }
        owner {
          login
          __typename
        }
        createdAt
        updatedAt
        repositoryTopics(first: 10) {
          nodes {
            topic {
              name
            }
          }
        }
      }
    }
  }
  rateLimit {
    limit
    remaining
    resetAt
  }
}
